import pathlib
from typing import Optional

from taf.ul.ue.sim.env_setup.utils.scfc_utils import get_dict_from_xml, save_dict_to_xml


class VendorModifier:
    def __init__(self, vendor_params: list[str], output_directory_path: str) -> None:
        self._vendor_params = vendor_params
        self._output_directory_path = pathlib.Path(output_directory_path)
        self._vendor_path = self._output_directory_path.joinpath("vendor.xml")
        self._modified_vendor_path = self._output_directory_path.joinpath("MODIFIED_vendor.xml")

    def modify(self) -> pathlib.Path:
        vendor_file_dict = get_dict_from_xml(self._vendor_path)
        for vendor_param in self._vendor_params:
            try:
                param_path, value = vendor_param.strip().split("=")
            except ValueError:
                raise AttributeError(
                    f"Wrong format of vendor parameter {vendor_param}. Expected equal sign (PARAM=VALUE)."
                )
            params_path = param_path.lower().split(".")
            if len(params_path) == 2:
                self._modify_for_single_param(params_path, value, vendor_file_dict)
            elif len(params_path) == 3:
                self._modify_for_param_in_list(params_path, value, vendor_file_dict)
            else:
                raise AttributeError(
                    f"Wrong format of vendor parameter {vendor_param}. "
                    "Expected dotted format (MOC.PARAM=VALUE or MOC.LIST.PARAM=VALUE)."
                )
        save_dict_to_xml(
            vendor_file_dict,
            self._modified_vendor_path,
        )
        return self._modified_vendor_path

    def _modify_for_single_param(self, params_path: list[str], value: str, vendor_file_dict: dict) -> None:
        param_managed_object, param_name = params_path
        self.__search_for_moc(param_managed_object, param_name, value, vendor_file_dict)

    def _modify_for_param_in_list(self, params_path: list[str], value: str, vendor_file_dict: dict) -> None:
        param_managed_object, param_list_object, param_name = params_path
        self.__search_for_moc(param_managed_object, param_name, value, vendor_file_dict, param_list_object)

    def __search_for_moc(
        self,
        param_managed_object: str,
        param_name: str,
        value: str,
        vendor_file_dict: dict,
        param_list_object: Optional[str] = None,
    ) -> None:
        for managed_object in vendor_file_dict["raml"]["cmData"]["managedObject"]:
            if managed_object["@class"].lower() == param_managed_object:
                if not param_list_object:
                    self.__search_param_and_modify_value(managed_object, param_name, value)
                else:
                    self.__search_list_and_param_in_moc(managed_object, param_list_object, param_name, value)

    def __search_param_and_modify_value(
        self, managed_object: dict, param_name: str, value: str, constraints: Optional[list[str]] = None
    ) -> None:
        for param in managed_object["p"]:
            if param["@name"].lower() == param_name:
                if self.__check_constraints(managed_object, constraints):
                    param["#text"] = value

    @staticmethod
    def __check_constraints(managed_object: dict, constraints: Optional[list[str]]) -> bool:
        if constraints is None:
            return True
        if all(_ in [param["#text"].lower() for param in managed_object["p"]] for _ in constraints):
            return True
        return False

    def __search_list_and_param_in_moc(
        self, managed_object: dict, param_list_object: str, param_name: str, value: str
    ) -> None:
        param_list_objects_split = param_list_object.strip().lower().split("___")
        list_name = param_list_objects_split[0]
        constraints = param_list_objects_split[1:]
        for list_of_params in managed_object["list"]:
            if list_of_params["@name"].lower() == list_name:
                self._search_param_in_list_and_modify_value(list_of_params, param_name, value, constraints)

    def _search_param_in_list_and_modify_value(
        self, list_of_params: dict, param_name: str, value: str, constraints: list[str]
    ) -> None:
        list_of_items = list_of_params["item"]
        if isinstance(list_of_items, list):  # list has lists inside, e.g. NRBTS.bbPoolCapacity
            for list_in_list_of_params in list_of_items:
                self.__search_param_and_modify_value(list_in_list_of_params, param_name, value, constraints)
        else:  # list has no lists inside, e.g. LNBTS.phyLoadThresholds
            self.__search_param_and_modify_value(list_of_items, param_name, value, constraints)
